            ${fields.map(Field).join("")}
            <p class="success-message" id="success-message" role="status">
              Thanks, your support contact details are ready to send.
            </p>
            <button type="submit">Submit request</button>
          </form>
        </section>
      `;
    }

    function App() {
      return ContactForm();
    }

    function validateField(input) {
      const field = fields.find((item) => item.id === input.id);
      const error = field.validate(input.value);
      const errorElement = document.getElementById(`${input.id}-error`);

      input.setAttribute("aria-invalid", error ? "true" : "false");
      errorElement.textContent = error;

      return !error;
    }

    function attachFormBehavior() {
      const form = document.getElementById("support-form");
      const successMessage = document.getElementById("success-message");

      fields.forEach(({ id }) => {
        const input = document.getElementById(id);

        input.addEventListener("blur", () => validateField(input));
        input.addEventListener("input", () => {
          successMessage.classList.remove("is-visible");

          if (input.getAttribute("aria-invalid") === "true") {
            validateField(input);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const isValid = fields
          .map(({ id }) => validateField(document.getElementById(id)))
          .every(Boolean);

        successMessage.classList.toggle("is-visible", isValid);

        if (isValid) {
          form.reset();
        }
      });
    }

    document.getElementById("root").innerHTML = App();
    attachFormBehavior();
  </script>
