  <main id="root" class="support-shell"></main>

  <script>
    const fields = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        placeholder: "Alex Morgan",
        autocomplete: "name",
        required: true,
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }

          if (value.trim().length < 2) {
            return "Please enter at least 2 characters.";
          }

          return "";
        }
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        placeholder: "alex@example.com",
        autocomplete: "email",
        required: true,
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
            return "Enter a valid email address.";
          }

          return "";
        }
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        placeholder: "+1 555 123 4567",
        autocomplete: "tel",
        required: false,
        helper: "Expected format: +1 555 123 4567, 555-123-4567, or another 7-15 digit phone number.",
        validate(value) {
          const trimmed = value.trim();

          if (!trimmed) {
            return "";
          }

          if (!/^\+?[0-9\s().-]{7,20}$/.test(trimmed) || trimmed.replace(/\D/g, "").length < 7) {
            return "Enter a valid phone number or leave this field blank.";
          }

          return "";
        }
      }
    ];

    function Field({ id, label, type, placeholder, autocomplete, required, helper }) {
      const requiredAttribute = required ? "required" : "";
      const optionalText = required ? "" : '<span class="optional">Optional</span>';
      const helperText = helper ? `<p class="helper-text" id="${id}-helper">${helper}</p>` : "";
      const describedBy = [helper ? `${id}-helper` : "", `${id}-error`].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${id}">
            <span>${label}</span>
            ${optionalText}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            placeholder="${placeholder}"
            autocomplete="${autocomplete}"
            ${requiredAttribute}
            aria-invalid="false"
            aria-describedby="${describedBy}"
          >
          ${helperText}
          <p class="error-message" id="${id}-error" aria-live="polite"></p>
        </div>
