      transform: translateY(0);
    }
  </style>
</head>
<body>
  <main id="root" class="support-shell"></main>

  <script>
    const fields = [
      {
        id: "fullName",
        label: "Full name",
        type: "text",
        placeholder: "Alex Morgan",
        autocomplete: "name",
        required: true,
        validate(value) {
          if (!value.trim()) {
            return "Full name is required.";
          }

          if (value.trim().length < 2) {
            return "Please enter at least 2 characters.";
          }

          return "";
        }
      },
      {
        id: "email",
        label: "Email address",
        type: "email",
        placeholder: "alex@example.com",
        autocomplete: "email",
        required: true,
        validate(value) {
          if (!value.trim()) {
            return "Email address is required.";
          }

          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) {
            return "Enter a valid email address.";
          }

          return "";
        }
      },
      {
        id: "phone",
        label: "Phone number",
        type: "tel",
        placeholder: "+1 555 123 4567",
        autocomplete: "tel",
        required: false,
        helper: "Expected format: +1 555 123 4567, 555-123-4567, or another 7-15 digit phone number.",
        validate(value) {
          const trimmed = value.trim();
          const digitCount = trimmed.replace(/\D/g, "").length;

          if (!trimmed) {
            return "";
          }

          if (!/^\+?[0-9\s().-]{7,20}$/.test(trimmed) || digitCount < 7 || digitCount > 15) {
            return "Enter a valid phone number or leave this field blank.";
          }

          return "";
        }
      }
    ];

    function Field({ id, label, type, placeholder, autocomplete, required, helper }) {
      const requiredAttribute = required ? "required" : "";
      const optionalText = required ? "" : '<span class="optional">Optional</span>';
      const helperText = helper ? `<p class="helper-text" id="${id}-helper">${helper}</p>` : "";
      const describedBy = [helper ? `${id}-helper` : "", `${id}-error`].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${id}">
            <span>${label}</span>
            ${optionalText}
          </label>
          <input
            id="${id}"
            name="${id}"
            type="${type}"
            placeholder="${placeholder}"
            autocomplete="${autocomplete}"
            ${requiredAttribute}
            aria-invalid="false"
            aria-describedby="${describedBy}"
          >
          ${helperText}
          <p class="error-message" id="${id}-error" aria-live="polite"></p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="support-card" aria-labelledby="support-title">
          <p class="eyebrow">Support desk</p>
          <h1 id="support-title">How can we help?</h1>
          <p class="intro">
            Send our team your contact details and we will route your request to the right support specialist.
          </p>
          <form id="support-form" novalidate>
            ${fields.map(Field).join("")}
            <p class="success-message" id="success-message" role="status">
              Thanks, your support contact details are ready to send.
            </p>
            <button type="submit">Submit request</button>
          </form>
        </section>
      `;
    }

    function App() {
      return ContactForm();
    }

    function validateField(input) {
      const field = fields.find((item) => item.id === input.id);
      const error = field.validate(input.value);
      const errorElement = document.getElementById(`${input.id}-error`);

      input.setAttribute("aria-invalid", error ? "true" : "false");
      errorElement.textContent = error;

      return !error;
    }

    function attachFormBehavior() {
      const form = document.getElementById("support-form");
      const successMessage = document.getElementById("success-message");

      fields.forEach(({ id }) => {
        const input = document.getElementById(id);

        input.addEventListener("blur", () => validateField(input));
        input.addEventListener("input", () => {
          successMessage.classList.remove("is-visible");

          if (input.getAttribute("aria-invalid") === "true") {
            validateField(input);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const isValid = fields
          .map(({ id }) => validateField(document.getElementById(id)))
          .every(Boolean);

        successMessage.classList.toggle("is-visible", isValid);

        if (isValid) {
          form.reset();
        }
      });
    }

    document.getElementById("root").innerHTML = App();
    attachFormBehavior();
  </script>
</body>
</html>
